import{_ as e,o as i,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2022-11-09","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2022-11-09","date":"2022-11-09T00:00:00.000Z","updated":"2022-11-09T00:00:00.000Z","tags":["Ceph","RGW","模块化","版本控制","代码清理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_RGW_Refactoring_Meeting_2022-11-09.md","filePath":"posts/2022/Ceph_RGW_Refactoring_Meeting_2022-11-09.md","lastUpdated":1780459816000}'),r={name:"posts/2022/Ceph_RGW_Refactoring_Meeting_2022-11-09.md"};function a(n,l,s,p,c,g){return i(),o("div",null,[...l[0]||(l[0]=[t('<p>本次会议主要讨论了Ceph存储系统中RGW（Rados Gateway）的代码重构问题，包括依赖管理、模块化、版本控制、代码清理等方面。</p><h2 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h2><ol><li><p><strong>依赖管理与组织结构</strong></p><ul><li>讨论了如何组织RGW的依赖，特别是处理外部树（out-of-tree）驱动程序的依赖关系。</li><li>探讨了是否应该让外部树驱动程序依赖于self common库，以及如何避免这种依赖。</li><li>讨论了如何处理编码解码（encode/decode）和配置（config）相关的依赖。</li></ul></li><li><p><strong>模块化与版本控制</strong></p><ul><li>讨论了如何通过模块化减少依赖，特别是如何处理rgw common库的复杂性。</li><li>探讨了版本控制的重要性，特别是如何确保第三方驱动程序能够兼容不同版本的Ceph。</li></ul></li><li><p><strong>代码清理与优化</strong></p><ul><li>讨论了如何清理不必要的头文件包含，以提高编译速度和代码质量。</li><li>探讨了如何通过分离文件和模块来优化代码结构，特别是如何处理DB store与rgw的循环依赖问题。</li></ul></li></ol><h2 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h2><ol><li><p><strong>依赖管理</strong></p><ul><li>决定避免外部树驱动程序直接依赖于self common库，考虑通过分离和标准化部分功能来减少依赖。</li></ul></li><li><p><strong>模块化与版本控制</strong></p><ul><li>决定逐步将rgw common库中的功能分离出来，形成更小的模块，以便更好地管理和控制依赖。</li><li>强调了版本控制的重要性，特别是如何确保第三方驱动程序的兼容性。</li></ul></li><li><p><strong>代码清理</strong></p><ul><li>决定通过分离文件和模块来优化代码结构，特别是将rados specific的代码移动到store rados目录下。</li><li>决定通过分离文件和模块来优化代码结构，特别是将rados specific的代码移动到store rados目录下。</li></ul></li></ol><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><ol><li><p><strong>依赖管理</strong></p><ul><li>继续研究和实施如何避免外部树驱动程序依赖于self common库。</li><li>考虑将部分功能从self common库中分离出来，形成独立的模块。</li></ul></li><li><p><strong>模块化与版本控制</strong></p><ul><li>继续推进rgw common库的模块化工作，形成更小的、独立的模块。</li><li>研究和实施版本控制策略，确保第三方驱动程序的兼容性。</li></ul></li><li><p><strong>代码清理</strong></p><ul><li>继续清理不必要的头文件包含，提高编译速度和代码质量。</li><li>通过分离文件和模块来优化代码结构，特别是处理DB store与rgw的循环依赖问题。</li></ul></li></ol>',7)])])}const u=e(r,[["render",a]]);export{d as __pageData,u as default};
